import React, { useState } from 'react';
import CameraScanner from './CameraScanner';
import RiskMeter from './RiskMeter';
import Tesseract from 'tesseract.js';
import './style.css';

function App() {

  const [capturedImage, setCapturedImage] = useState("");
  const [ocrText, setOcrText] = useState("");
  const [detectedCodes, setDetectedCodes] = useState([]);
  const [riskScore, setRiskScore] = useState(0);

  const handleCapture = async (image) => {

    setCapturedImage(image);

    try {

      console.log("Starting OCR...");

      const result = await Tesseract.recognize(
        image,
        "eng",
        {
          logger: m => console.log(m)
        }
      );

      const extractedText = result.data.text;

      console.log(
        "OCR Result:",
        extractedText
      );

      setOcrText(extractedText);

      // Extract INS numbers
      // Finds 211,415,260 etc.

      const codes =
        extractedText.match(/\b\d{3,4}\b/g) || [];

      const uniqueCodes =
        [...new Set(codes)];

      console.log(
        "Detected INS:",
        uniqueCodes
      );

      setDetectedCodes(uniqueCodes);

      // Temporary risk logic

      const score =
        uniqueCodes.length * 20;

      setRiskScore(score);

    }
    catch(error){

      console.log(
        "OCR Error:",
        error
      );
    }

  };

  return (

    <div className="app">

      <header className="hero">

        <h1>
          <b>SAFE BITE</b>
        </h1>

        <p>
          Scan food ingredients and detect harmful additives instantly
        </p>

      </header>

      <div className="main-container">

        <div className="left-side">

          <CameraScanner
            onCapture={handleCapture}
          />

          {capturedImage && (

            <div className="card">

              <h2>
                Captured Image
              </h2>

              <img
                src={capturedImage}
                alt="Captured"
                width="100%"
              />

            </div>

          )}

          <div className="card">

            <h2>
              OCR Result
            </h2>

            <p>

              {ocrText ||
                "No text detected"}

            </p>

          </div>

        </div>

        <div className="right-side">

          <div className="card">

            <h2>
              Food Risk Meter
            </h2>

            <RiskMeter
              score={riskScore}
            />

          </div>

          <div className="card">

            <h2>
              Detected INS Codes
            </h2>

            {

            detectedCodes.length > 0 ?

              detectedCodes.map(
                (code,index)=>(
                <div
                  className="ingredient-card"
                  key={index}
                >

                  <h3>

                    INS {code}

                  </h3>

                </div>
              ))

              :

              <p>

                No INS numbers detected

              </p>

            }

          </div>

        </div>

      </div>

    </div>

  );
}

export default App;
